import { CoreWebg2 } from './Core';
import { Scene } from './Scene';
export class WebGL2GLSL {
    divHost: HTMLElement;
    coreWebg2: CoreWebg2;
    scene: Scene;
    m: number[] = [];
    public static Init(id: string) {
        new WebGL2GLSL(id);
    }
    constructor(id: string) {
        const divHost = document.getElementById(id);
        if (divHost) {
            this.divHost = divHost;
            this.divHost.onmousemove = (e: MouseEvent) => {
                this.m[0] = e.x;
                this.m[1] = e.y;
            };
        }
        this.coreWebg2 = new CoreWebg2(this);
        this.scene = new Scene(this);
    }
}

export class Solution {
    public divHost: HTMLElement;

    constructor(id: string) {
        this.divHost = document.getElementById(id) as HTMLDivElement;

        WebGL2GLSL.Init(id)
    }
    public destroy() {
        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}